const crypto = require('crypto');
const secret = $env.QR_SIGNING_SECRET || 'medconnect-secret';
const dispatchId = $json.dispatch_id;
const reqId = $json.request_id;
const issuedAt = new Date().toISOString();
const exp = new Date(Date.now() + 60 * 60 * 1000).toISOString();

const raw = `${dispatchId}:${reqId}:${issuedAt}`;
const signature = crypto.createHmac('sha256', secret).update(raw).digest('hex');

return { json: { dispatch_id: dispatchId, request_id: reqId, issued_at: issuedAt, exp, signature } };
